node -e '
const { neon } = require("@neondatabase/serverless");
const sql = neon(process.env.DATABASE_URL);
async function run() {
  console.log("Enabling Row Level Security on tables...");
  await sql`ALTER TABLE rooms ENABLE ROW LEVEL SECURITY`;
  await sql`ALTER TABLE liturgical_blocks ENABLE ROW LEVEL SECURITY`;

  // Create policy allowing access to application queries
  await sql`
    DO $$
    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = '\''rooms'\'' AND policyname = '\''allow_app_access_rooms'\''
      ) THEN
        CREATE POLICY allow_app_access_rooms ON rooms FOR ALL USING (true) WITH CHECK (true);
      END IF;
    END
    $$;
  `;

  await sql`
    DO $$
    BEGIN
      IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = '\''liturgical_blocks'\'' AND policyname = '\''allow_app_access_blocks'\''
      ) THEN
        CREATE POLICY allow_app_access_blocks ON liturgical_blocks FOR ALL USING (true) WITH CHECK (true);
      END IF;
    END
    $$;
  `;

  const check = await sql`
    SELECT relname, relrowsecurity 
    FROM pg_class 
    WHERE relname IN ('\''rooms'\'', '\''liturgical_blocks'\'')
  `;
  console.log("RLS Status:", check);
}
run().catch(console.error);
'

